#include <stdio.h>
#include <string.h>

#define MAXN 100005
#define LOG 18

int p[MAXN];
int head[MAXN], to[MAXN], nxt[MAXN], edge_cnt = 0;
int tin[MAXN], tout[MAXN], timer = 0;
int up[LOG][MAXN];
int lazy[4 * MAXN];

void add_edge(int u, int v) {
    to[edge_cnt] = v;
    nxt[edge_cnt] = head[u];
    head[u] = edge_cnt++;
}

void update(int node, int l, int r, int ql, int qr, int val) {
    if (ql <= l && r <= qr) {
        lazy[node] = val;
        return;
    }
    if (lazy[node] != 0) {
        lazy[node * 2] = lazy[node];
        lazy[node * 2 + 1] = lazy[node];
        lazy[node] = 0;
    }
    int mid = (l + r) / 2;
    if (ql <= mid) update(node * 2, l, mid, ql, qr, val);
    if (qr > mid) update(node * 2 + 1, mid + 1, r, ql, qr, val);
}

int query(int node, int l, int r, int pos) {
    if (lazy[node] != 0) return lazy[node];
    if (l == r) return 0;
    int mid = (l + r) / 2;
    if (pos <= mid) return query(node * 2, l, mid, pos);
    else return query(node * 2 + 1, mid + 1, r, pos);
}

int kth_ancestor(int x, int d) {
    for (int j = 0; j < LOG; j++) {
        if (d & (1 << j)) {
            x = up[j][x];
        }
    }
    return x;
}

int main() {
    int N;
    scanf("%d", &N);
    memset(head, -1, sizeof(head));
    for (int i = 2; i <= N; i++) {
        scanf("%d", &p[i]);
        add_edge(p[i], i);
    }
    p[1] = 0;

    int it[MAXN];
    for (int i = 1; i <= N; i++) it[i] = head[i];
    int stack[MAXN], top = 0;
    stack[0] = 1;
    while (top >= 0) {
        int u = stack[top];
        if (tin[u] == 0) {
            tin[u] = ++timer;
        }
        if (it[u] != -1) {
            int v = to[it[u]];
            it[u] = nxt[it[u]];
            stack[++top] = v;
        } else {
            tout[u] = timer;
            top--;
        }
    }

    for (int i = 1; i <= N; i++) up[0][i] = (i == 1) ? 0 : p[i];
    for (int j = 1; j < LOG; j++) {
        for (int i = 1; i <= N; i++) {
            up[j][i] = up[j - 1][ up[j - 1][i] ];
        }
    }

    memset(lazy, 0, sizeof(lazy));

    int Q;
    scanf("%d", &Q);
    while (Q--) {
        int type;
        scanf("%d", &type);
        if (type == 1) {
            int v, k;
            scanf("%d %d", &v, &k);
            int active = query(1, 1, N, tin[v]);
            int ans;
            if (active == 0 || active == v) {
                ans = kth_ancestor(v, k);
            } else {
                if (k == 1) ans = active;
                else ans = kth_ancestor(active, k - 1);
            }
            printf("%d\n", ans);
        } else {
            int v;
            scanf("%d", &v);
            int active = query(1, 1, N, tin[v]);
            if (active == 0) {
                update(1, 1, N, tin[v], tout[v], v);
            }
        }
    }
    return 0;
}
